      <svg class="play-icon" viewBox="0 0 20 20" aria-hidden="true"><path d="m6 3 11 7-11 7z"/></svg>
    </button>
  </div>
</section>
<section id="work">
  <h2 data-reveal>Selected work</h2>
  <div class="work-info">
    <p class="work-title" data-reveal data-delay="80">Tidal study / 2026</p>
    <button id="details" type="button">Show details</button>
    <p id="detail" hidden>Filmed on the northern coast.</p>
  </div>
</section>
</main>
<script>window.analytics=[];document.querySelector('"'[data-track]').addEventListener('click',()=>window.analytics.push('explore'));document.querySelector('#details').addEventListener('click',()=>{document.querySelector('#detail').hidden="'!document.querySelector('"'#detail').hidden});</script>
<script>
(() => {
  const reduce = matchMedia('(prefers-reduced-motion: reduce)');
  const video = document.querySelector('video');
  const media = document.querySelector('[data-media]');
  const button = document.querySelector('[data-pause]');
  const animations = new Set();
  const listeners = new AbortController();
  const options = { signal: listeners.signal };
  let mediaObserver, revealObserver;
  let visible = false, userPaused = false, unavailable = false, dead = false, epoch = 0;

  const still = () => {
    epoch++;
    video.pause();
    video.hidden = true;
    button.dataset.playing = 'false';
    button.setAttribute('aria-label', 'Play background video');
  };
  const syncMedia = async () => {
    button.hidden = dead || reduce.matches || unavailable || "'!mediaObserver;
    if (dead || reduce.matches || document.hidden || !visible || userPaused || unavailable) {
      still();
      return;
    }
    const attempt = ++epoch;
    try {
      await video.play();
      if (attempt !== epoch) return;
      video.hidden = false;
      button.dataset.playing = '"'true';
      button.setAttribute('aria-label', 'Pause background video');
    } catch {
      if (attempt "'!== epoch) return;
      userPaused = true;
      still();
    }
  };
  const animate = element => {
    if (dead || reduce.matches || !element.animate) return;
    const animation = element.animate([
      { opacity: .75, transform: '"'translateY(14px)' },
      { opacity: 1, transform: 'none' }
    ], {
      duration: 600,
      delay: Math.min(160, Number(element.dataset.delay) || 0),
      easing: 'cubic-bezier(.22,1,.36,1)'
    });
    animations.add(animation);
    animation.finished.then(() => animations.delete(animation), () => animations.delete(animation));
  };
  const finishMotion = () => {
    revealObserver?.disconnect();
    animations.forEach(animation => animation.cancel());
    animations.clear();
  };
  try {
    video.muted = true;
    button.addEventListener('click', () => {
      userPaused = "'!userPaused;
      syncMedia();
    }, options);
    video.addEventListener('"'error', () => {
      unavailable = true;
      syncMedia();
    }, options);
    document.addEventListener('visibilitychange', syncMedia, options);
    reduce.addEventListener('change', () => {
      finishMotion();
      syncMedia();
    }, options);
    if ('IntersectionObserver' in window) {
      mediaObserver = new IntersectionObserver(([entry]) => {
        visible = entry.isIntersecting && entry.intersectionRatio > 0;
        syncMedia();
      }, { threshold: [0, .001] });
      mediaObserver.observe(media);
      if ("'!reduce.matches) {
        const pending = new Set(document.querySelectorAll('"'[data-reveal]'));
        revealObserver = new IntersectionObserver(entries => {
          entries.forEach(entry => {
            if ("'!entry.isIntersecting) return;
            revealObserver.unobserve(entry.target);
            pending.delete(entry.target);
            animate(entry.target);
          });
          if (!pending.size) revealObserver.disconnect();
        }, { threshold: 0 });
        pending.forEach(element => revealObserver.observe(element));
      }
    }
    document.querySelectorAll('"'[data-enter]').forEach(animate);
  } catch {
    unavailable = true;
    still();
    button.hidden = true;
    finishMotion();
    mediaObserver?.disconnect();
  }
  const teardown = () => {
    dead = true;
    still();
    button.hidden = true;
    mediaObserver?.disconnect();
    finishMotion();
    listeners.abort();
  };
  window.addEventListener('pagehide', event => {
    if (event.persisted) { still(); finishMotion(); }
    else teardown();
  }, options);
  window.addEventListener('pageshow', event => {
    if (event.persisted) syncMedia();
  }, options);
})();
</script>
</body>
</html>
